import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.PrintWriter;
import java.util.logging.Logger;

@WebServlet("/admin/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String searchTerm = req.getParameter("q");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Missing search parameter");
            return;
        }

        // Validate sort column against whitelist
        String validSort = "username";
        if (sortCol != null && (sortCol.equals("email") || sortCol.equals("created_at") || sortCol.equals("username"))) {
            validSort = sortCol;
        }

        // Build query - department filter uses parameterized query
        // but searchTerm is concatenated for LIKE wildcard support
        String query = "SELECT username, email, department, created_at FROM app_users " +
                       "WHERE (username LIKE '%" + searchTerm + "%' OR email LIKE '%" + searchTerm + "%') ";

        if (department != null && !department.isEmpty()) {
            query += "AND department = ? ";
        }
        query += "ORDER BY " + validSort + " ASC LIMIT 50";

        log.info("User search executed: term=" + searchTerm.substring(0, Math.min(searchTerm.length(), 20)));

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.prepareStatement(query);

            if (department != null && !department.isEmpty()) {
                stmt.setString(1, department);
            }

            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.print("{\"username\":\"" + escapeJson(rs.getString("username")) + "\",");
                out.print("\"email\":\"" + escapeJson(rs.getString("email")) + "\",");
                out.print("\"department\":\"" + escapeJson(rs.getString("department")) + "\",");
                out.print("\"created_at\":\"" + escapeJson(rs.getString("created_at")) + "\"}");
                first = false;
            }
            out.print("]}");
        } finally {
            if (rs != null) rs.close();
            if (stmt != null) stmt.close();
            if (conn != null) conn.close();
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
